#!/usr/bin/env bash
# Experimental PMTP smoke training. Run from the repository root on Linux/CUDA.
# DATA must contain conversations, preferably generated by the target checkpoint.
set -euo pipefail

: "${DATA:?Set DATA to a conversation JSON/JSONL dataset}"
: "${VLLM_GPUS:?Set VLLM_GPUS to the comma-separated verifier GPU IDs}"
: "${TRAIN_GPU:?Set TRAIN_GPU to one separate training GPU ID}"
: "${VLLM_PYTHON:?Set VLLM_PYTHON to the vLLM environment Python}"
: "${TRAIN_PYTHON:?Set TRAIN_PYTHON to the Speculators environment Python}"

MODEL="${MODEL:-Qwen/Qwen3.5-35B-A3B}"
OUTPUT_DIR="${OUTPUT_DIR:-./output/pmtp-35b-$(date +%Y%m%d-%H%M%S)}"
PORT="${PORT:-8000}"
SEQ_LENGTH="${SEQ_LENGTH:-2048}"
IFS=',' read -r -a verifier_gpus <<< "$VLLM_GPUS"
TP="${TP:-${#verifier_gpus[@]}}"
for gpu in "${verifier_gpus[@]}"; do
    if [[ "$gpu" == "$TRAIN_GPU" ]]; then
        echo 'TRAIN_GPU must be separate from VLLM_GPUS.' >&2
        exit 1
    fi
done
if [[ "$TRAIN_GPU" == *,* ]]; then
    echo 'This smoke recipe uses one training GPU; use torchrun for FSDP runs.' >&2
    exit 1
fi
if curl -sf "http://localhost:$PORT/health" >/dev/null; then
    echo "Port $PORT already serves a model; select a free PORT." >&2
    exit 1
fi
mkdir -p "$OUTPUT_DIR"
OUTPUT_DIR="$(cd "$OUTPUT_DIR" && pwd)"
CHECKPOINTS="$OUTPUT_DIR/checkpoints"
HIDDEN_STATES="$OUTPUT_DIR/hidden_states"
mkdir -p "$CHECKPOINTS" "$HIDDEN_STATES"

# Qwen3.5-35B-A3B has 40 text layers; derive the index to support local copies.
LAST_LAYER="$("$TRAIN_PYTHON" -c \
    'import sys; from transformers import AutoConfig; print(AutoConfig.from_pretrained(sys.argv[1]).get_text_config().num_hidden_layers)' \
    "$MODEL")"

CUDA_VISIBLE_DEVICES="$VLLM_GPUS" "$VLLM_PYTHON" scripts/launch_vllm.py train "$MODEL" \
    --target-layer-ids "$LAST_LAYER" \
    --hidden-states-path "$HIDDEN_STATES" \
    --provenance-dir "$CHECKPOINTS" \
    -- --port "$PORT" --tensor-parallel-size "$TP" \
    --max-model-len "$SEQ_LENGTH" --no-enable-chunked-prefill \
    >"$OUTPUT_DIR/vllm.log" 2>&1 &
VLLM_PID=$!
cleanup() {
    kill "$VLLM_PID" 2>/dev/null || true
    wait "$VLLM_PID" 2>/dev/null || true
}
trap cleanup EXIT
deadline=$((SECONDS + ${STARTUP_TIMEOUT:-1800}))
until curl -sf "http://localhost:$PORT/health" >/dev/null; do
    if ! kill -0 "$VLLM_PID" 2>/dev/null || (( SECONDS >= deadline )); then
        echo "vLLM failed to start; see $OUTPUT_DIR/vllm.log" >&2
        exit 1
    fi
    sleep 2
done

"$TRAIN_PYTHON" -m speculators prepare-data \
    --model "$MODEL" --data "$DATA" \
    --render-endpoint "http://localhost:$PORT" \
    --max-samples "${MAX_SAMPLES:-1000}" \
    --output "$OUTPUT_DIR/data" --seq-length "$SEQ_LENGTH"

CUDA_VISIBLE_DEVICES="$TRAIN_GPU" "$TRAIN_PYTHON" -m speculators.train \
    --speculator-type pmtp --verifier-name-or-path "$MODEL" \
    --data-path "$OUTPUT_DIR/data" --save-path "$CHECKPOINTS" \
    --vllm-endpoint "http://localhost:$PORT/v1" \
    --hidden-states-path "$HIDDEN_STATES" --on-missing generate \
    --num-speculative-steps 4 --step-weight-beta 0.6 \
    --pmtp-max-anchors "${MAX_ANCHORS:-32}" --pmtp-logit-chunk-size 16 \
    --loss-fn ce --total-seq-len "$SEQ_LENGTH" \
    --epochs "${EPOCHS:-1}" --max-steps "${MAX_STEPS:-50}" \
    --lr "${LR:-1e-4}" "$@"

echo "Experimental checkpoint and provenance: $CHECKPOINTS"
echo 'PMTP requires a parallel inference proposer; do not use stitch-mtp.'
